//go:build windows
package platform
import("errors";"os";"path/filepath";"strings";"unsafe";"golang.org/x/sys/windows")
func FreeBytes(folder string)(uint64,error){for {if _,e:=os.Stat(folder);e==nil{break};parent:=filepath.Dir(folder);if parent==folder{return 0,errors.New("диск недоступен")};folder=parent};p,e:=windows.UTF16PtrFromString(folder);if e!=nil{return 0,e};var free,total,available uint64;e=windows.GetDiskFreeSpaceEx(p,&available,&total,&free);return available,e}
func GameRunning(root string)bool {snapshot,e:=windows.CreateToolhelp32Snapshot(windows.TH32CS_SNAPPROCESS,0);if e!=nil{return true};defer windows.CloseHandle(snapshot);entry:=windows.ProcessEntry32{Size:uint32(unsafe.Sizeof(windows.ProcessEntry32{}))};for e=windows.Process32First(snapshot,&entry);e==nil;e=windows.Process32Next(snapshot,&entry){name:=windows.UTF16ToString(entry.ExeFile[:]);if !strings.EqualFold(name,"l2.exe"){continue};process,err:=windows.OpenProcess(windows.PROCESS_QUERY_LIMITED_INFORMATION,false,entry.ProcessID);if err!=nil{return true};buffer:=make([]uint16,32768);size:=uint32(len(buffer));err=windows.QueryFullProcessImageName(process,0,&buffer[0],&size);windows.CloseHandle(process);if err!=nil{return true};full:=windows.UTF16ToString(buffer[:size]);relative,err:=filepath.Rel(root,full);if err==nil&&relative!=".."&&!strings.HasPrefix(relative,".."+string(os.PathSeparator)){return true}};return false}
